import fcntl,json,math,sys
sys.path.insert(0,'/home/nvidia/tianji-robot-SDK/PYTHON_SDK')
from GentoRobot import GentoRobot
with open('/tmp/gento_sdk_6_6_7_190.lock','a+') as lock:
 fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 robot=GentoRobot()
 try:
  code=robot.link(6,6,7,190)
  if not robot._connected: raise RuntimeError('SDK link failed: '+str(code))
  result={}
  for arm in (0,1):
   rows=[]
   for j in range(7):
    row={'joint':j+1,'parameter_link_index':j}
    for field in ('VelMax','AccMax'):
     name='R.A%d.L%d.BASIC.%s'%(arm,j,field)
     ret,value=robot.param_get_float(name)
     row[field]={'name':name,'return_code':ret,'value':value}
     if ret or not math.isfinite(value) or value<=0: raise RuntimeError('Invalid parameter: '+name)
    rows.append(row)
   result['arm%d'%arm]=rows
  rt,sg=robot.get_rt_dict(),robot.get_sg_dict()
  print(json.dumps({'event':'arm_speed_parameters','parameters':result,'ratios':{str(i):sg['arms'][i]['set'] for i in (0,1)},'pose':{'arm0':rt['arms'][0]['fb']['fb_pos'],'arm1':rt['arms'][1]['fb']['fb_pos'],'body':rt['body']['fb_pos']},'motion_commands_sent':0,'parameter_writes_sent':0}),flush=True)
 finally:
  if robot._connected: robot.unlink()

